const data = $input.first().json;

const dateOfBirth = data.date_of_birth
  ? new Date(data.date_of_birth)
      .toISOString()
      .slice(0, 10)
  : "Not specified";

const consultations = Array.isArray(data.consultations)
  ? data.consultations
  : [];

const consultationLinks = consultations
  .map((c) => {
    return `- [[${data.patient_id}/Consultations/${c.consultation_id}]]`;
  })
  .join("\n");

const markdown = `# Patient

## Patient Information

- Patient ID: ${data.patient_id}
- First Name: ${data.first_name}
- Last Name: ${data.last_name}
- Date of Birth: ${dateOfBirth}

## Consultations

${consultationLinks || "- None"}
`;

return [
  {
    json: {
      ...data,
      patient_filename: "Patient.md",
      patient_path: `/data/obsidian/Patients/${data.patient_id}/Patient.md`,
      patient_markdown: markdown,
    },
  },
];

const data = $('Patient/Consultation-Node').first().json;

return [
  {
    json: {
      patient_id: data.patient_id,
      consultation_id: data.consultation_id
    }
  }
];
